insert into v2_theme_templates(name,slug,description,category,features,is_official,is_featured,is_published,structure_json,preview_url) select 'Flüt','flut','Mayo, iç giyim ve fantazi giyim için siyah-altın, krem zeminli lüks editöryel moda teması.','fashion','["Tam ekran editöryel hero ve altın vurgular", "Kayan altın yazı şeridi", "İkinci görselli, hızlı bakışlı ürün kartları", "Lookbook, spotlight ve Instagram alanı"]'::jsonb,true,true,true,structure,'/demo/flut' from v2_theme_presets where name='Flüt' limit 1 on conflict (slug) do nothing;